head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[multiselect > P > dataListAutoRefresh]<br/>MultiSelect 컴포넌트의 아이템 삭제 시 바인딩된 DataList 를 자동으로 갱신할지 설정합니다.",
    "validation" : [
        "BindItemSet 으로 DataList 와 바인딩된 경우에만 동작하며, 바인딩되지 않은 경우에는 내부 아이템 배열만 조작됩니다.",
        "true 설정 시 아이템 삭제(deleteItem/deleteSelectedItems) 시 바인딩된 DataList 의 해당 Row 가 함께 제거됩니다.",
        "false (default) 설정 시 아이템 삭제 시 바인딩된 DataList 를 제거하지 않고 화면의 아이템만 제거됩니다.",
        "속성값 미설정 시 기본값 false 가 적용되어 DataList 가 갱신되지 않습니다.",
        "deleteItem() 메소드에 refresh 파라미터가 명시적으로 전달되면 해당 속성값은 무시되고 파라미터값이 우선 적용됩니다.",
        "deleteSelectedItems() 메소드에 refresh 파라미터가 명시적으로 전달되면 해당 속성값은 무시되고 파라미터값이 우선 적용됩니다.",
        "addItem() 메소드는 refresh 파라미터가 지정되지 않은 경우 해당 속성값과 관계없이 항상 DataList 를 자동으로 갱신합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (createBasicMultiSelect 로 동적 생성, dataListAutoRefresh 속성 적용)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // gdl_multiselect 재생성 (idempotent: 기존 dataList 제거 후 재생성)
    $c.gcm.createDataListMultiSelect();

    let properties = {
        dataListAutoRefresh : con_dataListAutoRefresh.getText(),
    }

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createBasicMultiSelect(cList);
}



// 선택한 메서드 + refresh 파라미터로 실행
scwin.btn_execute_onclick = function (e) {
    let method = par_method.getText();
    let refresh = par_refresh.getText();
    let refreshLabel = (refresh === "") ? "생략" : refresh;

    if (method === "addItem") {
        let value = target1.getItemCount() + 1;
        let label = "add_Item" + value;
        if (refresh === "") {
            target1.addItem(value, label);
        } else {
            target1.addItem(value, label, undefined, (refresh === "true"));
        }
        wf_body_bottom.getObj("scwin").setReturnValue("addItem(value=" + value + ", label=" + label + ", refresh=" + refreshLabel + ") 실행");
    } else if (method === "deleteItem") {
        let index = target1.getItemCount() - 1;
        if (refresh === "") {
            target1.deleteItem(index);
        } else {
            target1.deleteItem(index, (refresh === "true"));
        }
        wf_body_bottom.getObj("scwin").setReturnValue("deleteItem(index=" + index + ", refresh=" + refreshLabel + ") 실행");
    } else if (method === "deleteSelectedItems") {
        if (refresh === "") {
            target1.deleteSelectedItems();
        } else {
            target1.deleteSelectedItems(refresh === "true");
        }
        wf_body_bottom.getObj("scwin").setReturnValue("deleteSelectedItems(refresh=" + refreshLabel + ") 실행");
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("par_method 를 선택하세요");
    }
};



// 바인딩된 DataList 의 현재 값 확인
scwin.btn_getDataList_onclick = function (e) {
    let rsData = gdl_multiselect.getAllJSON();

    wf_body_bottom.getObj("scwin").setReturnValue("DataList Row 수 : " + rsData.length);
    for (let i = 0; i < rsData.length; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("item 값 : " + rsData[i].label);
    }
};
